/* Single post: the handoff's article head. The build writes the post's date in
   the masthead and its category, read time and author as one line of text in
   the post's first block; this splits them into the tag + meta row and the
   author row, and adds the way back to the index. Everything it touches is
   already on the page and in order without it (the template's CSS orders it). */
(function () {
  var article = document.querySelector('main > article');
  if (!article) return;
  var base = location.pathname.replace(/\/[^/]+\/?$/, '') || '/blog';

  var back = document.createElement('div');
  back.className = 'bnb-back';
  var backLink = document.createElement('a');
  backLink.href = base;
  backLink.textContent = '← Back to blog';
  back.appendChild(backLink);
  article.insertBefore(back, article.firstChild);

  var meta = article.querySelector('[data-bz-node="post-meta"] p');
  var dateEl = article.querySelector('.bz-prose > .bz-eyebrow');
  if (meta) {
    var text = meta.textContent || '';
    var cat = meta.querySelector('strong');
    var read = (text.match(/(\d+)\s*min read/i) || [])[1];
    var author = ((text.match(/\bBy\s+(.+)$/i) || [])[1] || '').trim();
    var when = [dateEl ? dateEl.textContent.trim() : '', read ? read + ' min read' : ''].filter(Boolean).join(' · ');

    meta.textContent = '';
    if (cat) {
      var tag = document.createElement('span');
      tag.className = 'bnb-tag';
      tag.textContent = cat.textContent;
      meta.appendChild(tag);
    }
    var line = document.createElement('span');
    line.textContent = when;
    meta.appendChild(line);
    article.classList.add('bnb-enhanced');

    if (author) {
      var row = document.createElement('div');
      row.className = 'bnb-author';
      var avatar = document.createElement('span');
      avatar.className = 'bnb-author__avatar';
      avatar.setAttribute('aria-hidden', 'true');
      avatar.textContent = author.charAt(0).toUpperCase();
      var who = document.createElement('div');
      var name = document.createElement('strong');
      name.textContent = author;
      var org = document.createElement('span');
      org.textContent = 'Buzznerd';
      who.appendChild(name);
      who.appendChild(org);
      row.appendChild(avatar);
      row.appendChild(who);
      article.appendChild(row);
    }
  }

  /* More from the blog: never the post being read. Four are listed and three
     shown, so dropping this one leaves three. */
  var here = location.pathname.replace(/\/$/, '');
  Array.prototype.forEach.call(document.querySelectorAll('[data-bz-node="more"] a.bz-post'), function (card) {
    if (card.pathname.replace(/\/$/, '') === here) card.remove();
  });

  /* Keep the footer copyright year current (as the site template does). */
  var copy = document.querySelector('[data-bz-node="footer-copy"] p');
  if (copy) copy.innerHTML = copy.innerHTML.replace(/©\s*\d{4}/, '© ' + new Date().getFullYear());
})();

